        #endregion

        #region Fields

        private int _selectedEventIndex = -1;
        private int _editEventIndex = -1;
        private bool _isDialogOpen;
        private bool _isEditMode;
        private string _dialogTitle = "";
        private string _dialogYear = "";
        private string _dialogEventTitle = "";
        private string _dialogDescription = "";
        private string _dialogImageUrl = "";
        private string _yearValidationError = "";

        #endregion

        #region Properties

        public ObservableCollection<TimelineEvent> TimelineEvents { get; private set; }
        public ObservableCollection<TimelineNodeViewModel> DiagramNodes { get; private set; }
        public ObservableCollection<object> DiagramConnectors { get; private set; }

        public int SelectedEventIndex
        {
            get => _selectedEventIndex;
            set
            {
                _selectedEventIndex = value;
                OnPropertyChanged(nameof(SelectedEventIndex));
                OnPropertyChanged(nameof(CanShowAddHandle));
            }
        }

        /// <summary>
        /// True only when there is at least 1 year gap between
        /// selected node and the next node.
        /// e.g. selected=1993, next=1994 → NO gap → Add hidden
        ///      selected=1993, next=1995 → gap exists → Add visible
        /// </summary>
        public bool CanShowAddHandle
        {
            get
            {
                if (_selectedEventIndex < 0 ||
                    _selectedEventIndex >= TimelineEvents.Count - 1)
                    return false;

                // Parse current and next year
                bool currOk = int.TryParse(
                    TimelineEvents[_selectedEventIndex].Year, out int currYear);
                bool nextOk = int.TryParse(
                    TimelineEvents[_selectedEventIndex + 1].Year, out int nextYear);

                // Gap must be at least 2 so one year can be inserted between them
                return currOk && nextOk && (nextYear - currYear) >= 2;
            }
        }
        public bool IsDialogOpen
        {
            get => _isDialogOpen;
            set { _isDialogOpen = value; OnPropertyChanged(nameof(IsDialogOpen)); }
        }

        public bool IsEditMode
        {
            get => _isEditMode;
            set { _isEditMode = value; OnPropertyChanged(nameof(IsEditMode)); }
        }

        public string DialogTitle
        {
            get => _dialogTitle;
            set { _dialogTitle = value; OnPropertyChanged(nameof(DialogTitle)); }
        }

        public string DialogYear
        {
            get => _dialogYear;
            set { _dialogYear = value; OnPropertyChanged(nameof(DialogYear)); }
        }

        public string DialogEventTitle
        {
            get => _dialogEventTitle;
            set { _dialogEventTitle = value; OnPropertyChanged(nameof(DialogEventTitle)); }
        }

        public string DialogDescription
        {
            get => _dialogDescription;
            set { _dialogDescription = value; OnPropertyChanged(nameof(DialogDescription)); }
        }

        public string DialogImageUrl
        {
            get => _dialogImageUrl;
            set { _dialogImageUrl = value; OnPropertyChanged(nameof(DialogImageUrl)); }
        }

        public string YearValidationError
        {
            get => _yearValidationError;
            set { _yearValidationError = value; OnPropertyChanged(nameof(YearValidationError)); }
        }

        #endregion

        #region Commands

        public RelayCommand OpenAddDialogCommand { get; }
        public RelayCommand OpenEditDialogCommand { get; }
        public RelayCommand SubmitDialogCommand { get; }
        public RelayCommand CancelDialogCommand { get; }

        #endregion

        #region Constructor

        public HistoryTimelineViewModel()
        {
            DiagramNodes = new ObservableCollection<TimelineNodeViewModel>();
            DiagramConnectors = new ObservableCollection<object>();

            OpenAddDialogCommand = new RelayCommand(OnOpenAddDialog);
            OpenEditDialogCommand = new RelayCommand(OnOpenEditDialog);
            SubmitDialogCommand = new RelayCommand(OnSubmitDialog);
            CancelDialogCommand = new RelayCommand(_ => IsDialogOpen = false);

            TimelineEvents = new ObservableCollection<TimelineEvent>(GetDefaultEvents());
            RebuildDiagram();
        }

        #endregion

        #region Dialog Command Handlers

        /// <summary>
        /// Opens Add dialog.
        /// Uses _selectedEventIndex — NOT param — because QuickCommand
        /// fires AFTER SelectionChanged resets the selection.
        /// _selectedEventIndex is never reset on deselection so it is stable here.
        /// </summary>
        private void OnOpenAddDialog(object param)
        {
            int idx = _selectedEventIndex;
            if (idx < 0 || idx >= TimelineEvents.Count) return;

            _editEventIndex = idx;
            DialogYear = "";
            DialogEventTitle = "";
            DialogDescription = "";
            DialogImageUrl = "";
            YearValidationError = "";
            DialogTitle = "Add Event";
            IsEditMode = false;
            IsDialogOpen = true;
        }

        /// <summary>
        /// Opens Edit dialog.
        /// Same reasoning — uses _selectedEventIndex, not param.
        /// </summary>
        private void OnOpenEditDialog(object param)
        {
            int idx = _selectedEventIndex;
            if (idx < 0 || idx >= TimelineEvents.Count) return;

            _editEventIndex = idx;
            var ev = TimelineEvents[_editEventIndex];

            DialogYear = ev.Year;
            DialogEventTitle = ev.Title;
            DialogDescription = ev.Description;
            DialogImageUrl = ev.ImageUrl ?? "";
            YearValidationError = "";
            DialogTitle = "Edit Event";
            IsEditMode = true;
            IsDialogOpen = true;
        }

        private void OnSubmitDialog(object param)
        {
            if (!int.TryParse(DialogYear, out int parsedYear) ||
                parsedYear < 1900 || parsedYear > 2100)
            {
                YearValidationError = "Please enter a valid year (1900–2100).";
                return;
            }

            if (string.IsNullOrWhiteSpace(DialogEventTitle))
            {
                YearValidationError = "Title is required.";
                return;
            }

            if (IsEditMode)
            {
                bool duplicateEdit = TimelineEvents
                    .Where((e, i) => i != _editEventIndex)
                    .Any(e => e.Year == DialogYear);

                if (duplicateEdit)
                {
                    YearValidationError = $"Year {DialogYear} already exists.";
                    return;
                }

                if (_editEventIndex >= 0 && _editEventIndex < TimelineEvents.Count)
                {
                    var ev = TimelineEvents[_editEventIndex];
                    ev.Year = DialogYear;
                    ev.Title = DialogEventTitle;
                    ev.Description = DialogDescription;
                    ev.ImageUrl = string.IsNullOrWhiteSpace(DialogImageUrl)
                                     ? null : DialogImageUrl;
                    // Color and Icon stay unchanged on edit
                }
            }
            else
            {
                bool duplicate = TimelineEvents.Any(e => e.Year == DialogYear);
                if (duplicate)
                {
                    YearValidationError = $"Year {DialogYear} already exists.";
                    return;
                }

                if (_editEventIndex >= 0 &&
                    _editEventIndex < TimelineEvents.Count - 1)
                {
                    bool currOk = int.TryParse(
                        TimelineEvents[_editEventIndex].Year, out int currYear);
                    bool nextOk = int.TryParse(
                        TimelineEvents[_editEventIndex + 1].Year, out int nextYear);

                    if (currOk && nextOk &&
                        (parsedYear <= currYear || parsedYear >= nextYear))
                    {
                        YearValidationError =
                            $"Year must be between {currYear + 1} and {nextYear - 1}.";
                        return;
                    }
                }

                var newEvent = new TimelineEvent
                {
                    Year = DialogYear,
                    Title = DialogEventTitle,
                    Description = DialogDescription,
                    ImageUrl = string.IsNullOrWhiteSpace(DialogImageUrl)
                                  ? null : DialogImageUrl,
                    Icon = "Internet-Public",
                    Color = GetNextColor()
                };

                int insertAt = _editEventIndex + 1;
                if (insertAt >= TimelineEvents.Count)
                    TimelineEvents.Add(newEvent);
                else
                    TimelineEvents.Insert(insertAt, newEvent);
            }

            IsDialogOpen = false;
            RebuildDiagram();
        }

        private string GetNextColor()
        {
            var usedColors = new HashSet<string>(
                TimelineEvents
                    .Where(e => !string.IsNullOrEmpty(e.Color))
                    .Select(e => e.Color),
                StringComparer.OrdinalIgnoreCase);

            // Pick first unused color
            foreach (var c in EventColors)
                if (!usedColors.Contains(c)) return c;

            // All colors used — wrap by count
            return EventColors[TimelineEvents.Count % EventColors.Length];
        }
        #endregion

        #region Diagram Builder

        public void RebuildDiagram()
        {
            DiagramNodes.Clear();
            DiagramConnectors.Clear();

            if (TimelineEvents.Count == 0) return;

            // Sort by year — ensures correct index order after insert
            var sorted = TimelineEvents
                .OrderBy(e => int.TryParse(e.Year, out int y) ? y : 0)
                .ToList();

            TimelineEvents = new ObservableCollection<TimelineEvent>(sorted);
            OnPropertyChanged(nameof(TimelineEvents));

            CreateTimelineLineNode();

            for (int i = 0; i < TimelineEvents.Count; i++)
            {
                string id = TimelineEvents[i].Year;
                CreateYearMarkerNode(i, id);
                CreateEventNode(i, id);
                CreateConnectorNode(i, id);
            }
        }

        /// <summary>
        /// Dynamically builds gradient stops based on current event count.
        /// Each event gets exactly 1/count segment width so segments
        /// are always equal regardless of how many events exist.
        /// </summary>
        public GradientStopCollection BuildGradientStops()
        {
            var stops = new GradientStopCollection();
            int count = TimelineEvents.Count;
            if (count == 0) return stops;

            double segmentWidth = 1.0 / count;

            for (int i = 0; i < count; i++)
            {
                var color = (Color)ColorConverter.ConvertFromString(
                                TimelineEvents[i].Color);
                double start = i * segmentWidth;
                double end = (i + 1) * segmentWidth;

                stops.Add(new GradientStop(color, start));
                stops.Add(new GradientStop(color, end));
            }
            return stops;
        }

        private void CreateTimelineLineNode()
        {
            int count = TimelineEvents.Count;
            double lineWidth = count * NodeSpacing;
            double centerX = StartX + (count - 1) * NodeSpacing / 2.0;

            var brush = new LinearGradientBrush
            {
                StartPoint = new Point(0, 0),
                EndPoint = new Point(1, 0),
                GradientStops = BuildGradientStops()
            };

            var node = new TimelineNodeViewModel
            {
                ID = "timeline_line",
                OffsetX = centerX,
                OffsetY = BaseLine,
                UnitWidth = lineWidth,
                UnitHeight = 10,
                IsTimelineLine = true,
                DynamicBrush = brush,
                Constraints = NodeConstraints.None,
                ShapeStyle = TransparentShapeStyle()
            };
            node.Content = node;
            DiagramNodes.Add(node);
        }

        private void CreateYearMarkerNode(int index, string id)
        {
            var ev = TimelineEvents[index];

            var node = new TimelineNodeViewModel
            {
                ID = $"marker_{id}",
                OffsetX = StartX + index * NodeSpacing, 
                OffsetY = BaseLine,
                UnitWidth = 50,
                UnitHeight = 50,
                IsYearMarker = true,
                Year = ev.Year,
                EventIndex = index,
                Constraints = (NodeConstraints.Default)
                               & ~(NodeConstraints.Draggable | NodeConstraints.Delete),
                ShapeStyle = TransparentShapeStyle()
            };
            node.Content = node;
            DiagramNodes.Add(node);
        }
        private void CreateEventNode(int index, string id)
        {
            var ev = TimelineEvents[index];
            bool isOdd = (index + 1) % 2 != 0;
            if (!IconMap.TryGetValue(ev.Icon ?? "", out var iconPath))
                IconMap.TryGetValue("ARPANET", out iconPath);

            var node = new TimelineNodeViewModel
            {
                ID = $"event_{id}",
                OffsetX = StartX + index * NodeSpacing,
                OffsetY = isOdd ? StartY : BaseLine + AlternateOffset,
                UnitWidth = 130,
                UnitHeight = 100,
                EventBrush = new SolidColorBrush(
                                  (Color)ColorConverter.ConvertFromString(ev.Color)),
                Title = ev.Title,
                Year = ev.Year,

                IconPath = iconPath,
                ImageUrl = ev.ImageUrl,
                TooltipText = $"{ev.Year}: {ev.Description}",
                Constraints = NodeConstraints.Default
                              & ~(NodeConstraints.Selectable
                                  | NodeConstraints.Draggable
                                  | NodeConstraints.Delete),
                ShapeStyle = TransparentShapeStyle()
            };
            node.Content = node;
            DiagramNodes.Add(node);
        }

        private void CreateConnectorNode(int index, string id)
        {
            var ev = TimelineEvents[index];
            bool isOdd = (index + 1) % 2 != 0;

            var connector = new ConnectorViewModel
            {
                SourceNodeID = $"marker_{id}",
                TargetNodeID = $"event_{id}",
                Segments = new ObservableCollection<IConnectorSegment>
                {
                    new StraightSegment()
                },
                ConnectorGeometryStyle = new Style(typeof(System.Windows.Shapes.Path))
                {
                    Setters =
                    {
                        new Setter(System.Windows.Shapes.Shape.StrokeProperty,
                                   new SolidColorBrush(
                                       (Color)ColorConverter.ConvertFromString(ev.Color))),
                        new Setter(System.Windows.Shapes.Shape.StrokeThicknessProperty, 2.0)
                    }
                },
                TargetDecoratorStyle = new Style(typeof(System.Windows.Shapes.Path))
                {
                    Setters =
                    {
                        new Setter(System.Windows.Shapes.Shape.StrokeProperty, Brushes.Transparent),
                        new Setter(System.Windows.Shapes.Shape.FillProperty,   Brushes.Transparent)
                    }
                },
                Constraints = ConnectorConstraints.Default
                              & ~(ConnectorConstraints.Selectable
                                  | ConnectorConstraints.Draggable
                                  | ConnectorConstraints.Delete)
            };

            DiagramConnectors.Add(connector);
        }

        #endregion

        #region Helpers

        private Style TransparentShapeStyle() =>
            new Style(typeof(System.Windows.Shapes.Shape))
            {
                Setters =
                {
                    new Setter(System.Windows.Shapes.Shape.FillProperty,
                               Brushes.Transparent),
                    new Setter(System.Windows.Shapes.Shape.StrokeProperty,
                               Brushes.Transparent),
                    new Setter(System.Windows.Shapes.Shape.StrokeThicknessProperty,
                               0.0)
                }
            };

 

