    public class TimelineNodeViewModel : NodeViewModel
    {
        // ── Display data bound in DataTemplate ──────────────────────────────
        private string _title;
        private string _year;
        private string _iconUnicode;
        private string _imageUrl;
        private string _tooltipText;
        private Brush _eventBrush;
        private bool _isYearMarker;
        private bool _isTimelineLine;
        private int _eventIndex = -1; 

        private Brush _dynamicBrush;
        public Brush DynamicBrush
        {
            get => _dynamicBrush;
            set { _dynamicBrush = value; OnPropertyChanged(nameof(DynamicBrush)); }
        }

        private string _iconPath;

        public string IconPath
        {
            get => _iconPath;
            set { _iconPath = value; OnPropertyChanged(nameof(IconPath)); }
        }
        public string Title { get => _title; set { _title = value; OnPropertyChanged(nameof(Title)); } }
        public string Year { get => _year; set { _year = value; OnPropertyChanged(nameof(Year)); } }
        public string IconUnicode { get => _iconUnicode; set { _iconUnicode = value; OnPropertyChanged(nameof(IconUnicode)); } }
        public string ImageUrl { get => _imageUrl; set { _imageUrl = value; OnPropertyChanged(nameof(ImageUrl)); } }
        public string TooltipText { get => _tooltipText; set { _tooltipText = value; OnPropertyChanged(nameof(TooltipText)); } }
        public Brush EventBrush { get => _eventBrush; set { _eventBrush = value; OnPropertyChanged(nameof(EventBrush)); } }
        public bool IsYearMarker { get => _isYearMarker; set { _isYearMarker = value; OnPropertyChanged(nameof(IsYearMarker)); } }
        public bool IsTimelineLine { get => _isTimelineLine; set { _isTimelineLine = value; OnPropertyChanged(nameof(IsTimelineLine)); } }
        public int EventIndex { get => _eventIndex; set { _eventIndex = value; OnPropertyChanged(nameof(EventIndex)); } }
    }
